class Countup:
    def __init__(self, start, stop):
        self.current = start
        self.stop = stop

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.stop:
            raise StopIteration
        value = self.current
        self.current += 1
        return value

class Cycle:
    def __init__(self, items, times):
        self.items = items
        self.total = len(items) * times
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index >= self.total:
            raise StopIteration
        value = self.items[self.index % len(self.items)]
        self.index += 1
        return value

class Range2:
    def __init__(self, start, stop, step=1):
        self.start = start
        self.stop = stop
        self.step = step

    def __iter__(self):
        current = self.start
        while current < self.stop:
            yield current
            current += self.step

class Pages:
    def __init__(self, items, size):
        self.items = items
        self.size = size
        self.pos = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.pos >= len(self.items):
            raise StopIteration
        page = self.items[self.pos:self.pos + self.size]
        self.pos += self.size
        return page

_EMPTY = object()


class Peekable:
    def __init__(self, iterable):
        self.it = iter(iterable)
        self.buffer = _EMPTY

    def __iter__(self):
        return self

    def __next__(self):
        if self.buffer is not _EMPTY:
            value, self.buffer = self.buffer, _EMPTY
            return value
        return next(self.it)

    def peek(self, default=None):
        if self.buffer is _EMPTY:
            self.buffer = next(self.it, _EMPTY)
        return default if self.buffer is _EMPTY else self.buffer

