_END = object()


def merge_sorted(a, b):
    ia, ib = iter(a), iter(b)
    x, y = next(ia, _END), next(ib, _END)
    while x is not _END and y is not _END:
        if x <= y:
            yield x
            x = next(ia, _END)
        else:
            yield y
            y = next(ib, _END)
    while x is not _END:
        yield x
        x = next(ia, _END)
    while y is not _END:
        yield y
        y = next(ib, _END)

